#!/bin/sh
# Keycloak's own database and login role (ticket 49). Runs once, when the postgres-data
# volume is initialised; an older volume needs deploy/reset.sh first. The
# password comes from KC_DB_PASSWORD (generated by scripts/gen-dev-env.sh) and is passed
# as a psql variable, never written into this file.
set -eu
: "${KC_DB_PASSWORD:?KC_DB_PASSWORD is not set}"
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" -v kc_pw="$KC_DB_PASSWORD" <<'SQL'
CREATE ROLE keycloak LOGIN PASSWORD :'kc_pw';
CREATE DATABASE keycloak OWNER keycloak;
REVOKE ALL ON DATABASE keycloak FROM PUBLIC;
SQL
